<?php declare(strict_types=1);
$reportHeld=$reportState['values'];$reportShapeError=$reportState['unsupported'];
$reportChoices=['report_type'=>['label'=>'Auswertung','choices'=>['income'=>'Einnahmen & Ausgaben','journal'=>'Buchungsjournal (DATEV)']],'report_display'=>['label'=>'Darstellung','choices'=>['table'=>'Tabelle','chart'=>'Grafisch']],'resolution'=>['label'=>'Zeiteinteilung','choices'=>['week'=>'Woche','month'=>'Monat','year'=>'Jahr']],'compare'=>['label'=>'Vorjahresvergleich','choices'=>['0'=>'Ohne Vorjahresvergleich','1'=>'Mit Vorjahr vergleichen']]];
$reportRepairAccounts=(new \Kulturhus\Verein\Finance($db,(string)$_SESSION['actor']))->accounts();
$reportRawTags=$reportState['original_tags'];$reportHasTags=$reportRawTags!==[]&&$reportRawTags!=='';
$reportTagFields=static function(mixed $value,string $path)use(&$reportTagFields):void{if(is_array($value)){if($value===[]){echo hidden($path.'[unsupported_original_shape]','[]');return;}foreach($value as$key=>$item)$reportTagFields($item,$path.'['.$key.']');return;}if(is_string($value)||is_int($value))echo hidden($path,(string)$value);else echo hidden($path.'[unsupported_original]',json_encode($value,JSON_THROW_ON_ERROR));};
$reportWithoutTags=array_replace($_GET,['view'=>'finance','tab'=>'reports']);unset($reportWithoutTags['tags']);
?>
<link rel="stylesheet" href="finance-reports.css?v=2">
<section class="finance-report-errors" data-finance-report-errors aria-labelledby="finance-report-error-title">
<h2 id="finance-report-error-title"><?= $reportE('Übernommene Filter prüfen') ?></h2>
<p role="alert" id="finance-report-error-message"><?= $reportE($reportState['error']) ?></p>
<p><?= $reportE('Der Bericht wurde nicht geladen. Die ursprünglichen Filter bleiben zur Korrektur erhalten.') ?></p>
<?php if($reportShapeError): ?><label><?= $reportE('Nicht unterstützte Eingabe') ?><textarea class="form-control" rows="5" readonly data-report-unsupported><?= e(json_encode($reportShapeError,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)) ?></textarea></label><p><?= $reportE('Diese Eingabeform kann hier nicht bearbeitet werden. Öffne die Auswertungsfilter bewusst neu. Die bisherigen Angaben bleiben oben sichtbar.') ?></p><?php endif ?>
<form method="get" class="form-grid" data-report-repair><?= hidden('view','finance').hidden('tab','reports') ?>
<?php foreach($reportChoices as$reportField=>$reportChoice): ?><label><?= $reportE($reportChoice['label']) ?><select class="form-control" name="<?= e($reportField) ?>" aria-describedby="finance-report-error-message"><?php if(!array_key_exists($reportHeld[$reportField],$reportChoice['choices'])): ?><option value="<?= e($reportHeld[$reportField]) ?>" selected><?= $reportE('Auswahl prüfen') ?>: <?= e($reportHeld[$reportField]) ?></option><?php endif;foreach($reportChoice['choices']as$reportChoiceValue=>$reportChoiceLabel): ?><option value="<?= e((string)$reportChoiceValue) ?>" <?= $reportHeld[$reportField]===(string)$reportChoiceValue?'selected':'' ?>><?= $reportE($reportChoiceLabel) ?></option><?php endforeach ?></select></label><?php endforeach ?>
<?php foreach(['from'=>'Start des Zeitraums','to'=>'Ende des Zeitraums']as$reportField=>$reportLabel): ?><label><?= $reportE($reportLabel) ?><input class="form-control" type="text" name="<?= e($reportField) ?>" value="<?= e($reportHeld[$reportField]) ?>" required placeholder="YYYY-MM-DD" aria-describedby="finance-report-error-message"></label><?php endforeach ?>
<label><?= $reportE('Kontoauswahl') ?><select class="form-control" name="account" aria-describedby="finance-report-error-message"><option value="" <?= $reportHeld['account']===''?'selected':'' ?>><?= $reportE('Alle Konten') ?></option><?php if($reportHeld['account']!==''&&!in_array($reportHeld['account'],array_column($reportRepairAccounts,'id'),true)): ?><option value="<?= e($reportHeld['account']) ?>" selected><?= $reportE('Auswahl prüfen') ?>: <?= e($reportHeld['account']) ?></option><?php endif;foreach($reportRepairAccounts as$reportRepairAccount): ?><option value="<?= e($reportRepairAccount['id']) ?>" <?= $reportHeld['account']===$reportRepairAccount['id']?'selected':'' ?>><?= e($reportRepairAccount['name']) ?></option><?php endforeach ?></select></label>
<?php if($reportHasTags): ?><label><?= $reportE('Ursprünglicher Tagfilter') ?><textarea class="form-control" rows="3" readonly data-report-original-tags><?= e(json_encode($reportRawTags,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)) ?></textarea></label><?php $reportTagFields($reportRawTags,'tags'); ?><p><a class="btn btn-outline theme-secondary" data-report-clear-tags href="<?= e(url($reportWithoutTags)) ?>"><?= $reportE('Ohne Tagfilter auswerten') ?></a></p><?php endif ?>
<p><button class="btn btn-solid theme-primary" <?= $reportShapeError?'disabled':'' ?>><?= $reportE('Erstellen') ?></button></p></form>
<p><a class="btn btn-outline theme-secondary" data-report-reopen href="<?= e(url(['view'=>'finance','tab'=>'reports'])) ?>"><?= $reportE('Auswertungsfilter neu öffnen') ?></a></p><p><?= $reportE('Beim Neuöffnen werden unbestätigte Filter verworfen. Übernimm benötigte Angaben vorher.') ?></p>
</section>
